#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> values{"a", "b", "c"};
    auto count = values.size();        // std::size_t (unsigned), not int.
    bool ready{true};
    char grade{'A'};
    int score{0};                      // brace init: always initialised.
    double average{8.5};
    std::int64_t big{9'000'000'000};   // exactly 64 bits; ' separates digits.
    // int n{3.7};                     // error: narrowing double to int.
    std::cout << count << ' ' << grade << ' ' << big << '\n';
    return 0;
}
```

| Need | Type |
|---|---|
| true or false. | `bool`. |
| one character. | `char`. |
| ordinary whole numbers. | `int`. |
| container sizes and indexes. | `std::size_t` (what size() gives). |
| exact width. | `std::int32_t`, `std::int64_t`. |
| fractions. | `double`. |

